import os
import firebase_admin
from firebase_admin import credentials

def get_firebase_app():
    if not firebase_admin._apps:
        cred = credentials.Certificate(os.environ['FIREBASE_ADMIN_CREDENTIALS'])
        firebase_admin.initialize_app(cred)
    return firebase_admin.get_app()

from typing import Dict

def normalize_user_data(user_data: Dict) -> Dict:
    return {
        'email': user_data.get('email'),
        'password': user_data.get('password'),
        'display_name': user_data.get('displayName'),
        'photo_url': user_data.get('photoUrl')
    }

import boto3

def email_password_login(email, password, config=None):
    config = config or {}
    client = boto3.client('cognito-idp', region_name=config.get('region'))
    response = client.initiate_auth(
        ClientId=config['client_id'],
        AuthFlow='USER_PASSWORD_AUTH',
        AuthParameters={'USERNAME': email, 'PASSWORD': password}
    )
    return {'access_token': response['AuthenticationResult']['AccessToken'],
            'refresh_token': response['AuthenticationResult']['RefreshToken']}

import boto3

def refresh_session(refresh_token, config=None):
    config = config or {}
    client = boto3.client('cognito-idp', region_name=config.get('region'))
    response = client.initiate_auth(
        ClientId=config['client_id'],
        AuthFlow='REFRESH_TOKEN_AUTH',
        AuthParameters={'REFRESH_TOKEN': refresh_token}
    )
    return {'access_token': response['AuthenticationResult']['AccessToken'],
            'refresh_token': response['AuthenticationResult']['RefreshToken']}

import boto3

def password_reset(email, config=None):
    config = config or {}
    client = boto3.client('cognito-idp', region_name=config.get('region'))
    response = client.forgot_password(
        ClientId=config['client_id'],
        Username=email
    )
    return {'code_delivery_details': response['CodeDeliveryDetails']}
